import ctypes
import json

class gsl_matrix(ctypes.Structure):
    pass

class gsl_vector_complex(ctypes.Structure):
    pass

class gsl_eigen_nonsymm_workspace(ctypes.Structure):
    pass

gsl.gsl_eigen_nonsymm.argtypes = [
    ctypes.POINTER(gsl_matrix),
    ctypes.POINTER(gsl_vector_complex),
    ctypes.POINTER(gsl_eigen_nonsymm_workspace),
]

def create_gsl_matrix(matrix):
    n = len(matrix)
    gsl_matrix_ptr = gsl.gsl_matrix_alloc(n, n)
    for i in range(n):
        for j in range(n):
            gsl.gsl_matrix_set(gsl_matrix_ptr, i, j, matrix[i][j])
    return gsl_matrix_ptr

def create_gsl_vector_complex(size):
    gsl_vector_complex_ptr = gsl.gsl_vector_complex_alloc(size)
    return gsl_vector_complex_ptr

def compute_eigenvalues_nonsymm(matrix):
    n = len(matrix)
    gsl_matrix_ptr = create_gsl_matrix(matrix)
    gsl_vector_complex_ptr = create_gsl_vector_complex(n)
    gsl_eigen_nonsymm_workspace_ptr = gsl.gsl_eigen_nonsymm_alloc(n)
    gsl.gsl_eigen_nonsymm(gsl_matrix_ptr, gsl_vector_complex_ptr, gsl_eigen_nonsymm_workspace_ptr)
    eigenvalues = []
    for i in range(n):
        eigenvalues.append(gsl.gsl_vector_complex_get(gsl_vector_complex_ptr, i))
    return eigenvalues

