def matrix_to_gsl(matrix):
    rows, cols = len(matrix), len(matrix[0])
    gsl_matrix = gsl.gsl_matrix_new(rows, cols)
    gsl.gsl_matrix_set_size(gsl_matrix, rows, cols)
    for i in range(rows):
