class RingBuf:
    def __init__(self, size):
        self.ringbuf = gsl.gsl_ringbuf_alloc(size)

# Define the necessary functions
def initialize_ringbuf(size):
    return RingBuf(size)

def insert_into_ringbuf(ringbuf, values):
    for value in values:
        gsl.gsl_ringbuf_push(ringbuf.ringbuf, value)

def copy_ringbuf_to_list(ringbuf):
    result = []
    while True:
        value = gsl.gsl_ringbuf_pop(ringbuf.ringbuf)
        if value is None:
            break
        result.append(value)
    return result

