def create_histogram2d(nx, ny, xrange, yrange):
    # Validate input
    if nx <= 0 or ny <= 0:
        raise ValueError("nx and ny must be positive integers")
    if not isinstance(xrange, list) or not isinstance(yrange, list):
        raise ValueError("xrange and yrange must be lists")
    if not all(xrange[i] < xrange[i+1] for i in range(len(xrange)-1)):
        raise ValueError("xrange must be in increasing order")
    if not all(yrange[i] < yrange[i+1] for i in range(len(yrange)-1)):
        raise ValueError("yrange must be in increasing order")

    # Allocate memory
    histogram = GSL_Histogram2D()
    gsl.gsl_histogram2d_calloc_range(
        ctypes.byref(histogram),
        nx,
        ny,
        (ctypes.c_double*len(xrange))(*xrange),
        (ctypes.c_double*len(yrange))(*yrange)
    )

    # Return pointer to histogram
    return ctypes.pointer(histogram)

